WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('MONTH', prev_txn_time) AS activity_month, CASE WHEN island_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS island_id_tier, MAX(txn_time) AS last_txn_time, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, MIN(prev_txn_time) AS first_seen, STDDEV_SAMP(amount) AS amount_stddev, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list_2, RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', prev_txn_time) ORDER BY STDDEV_SAMP(amount) DESC) AS amount_stddev_rank FROM sessionized GROUP BY DATE_TRUNC('MONTH', prev_txn_time), CASE WHEN island_id >= 8 THEN 'HIGH' ELSE 'LOW' END HAVING amount_stddev >= 0
